import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./artwork/front.png',import.meta.url).href,back:new URL('./artwork/back.png',import.meta.url).href};export function addStickers(host){const layers=[];for(const face of['front','back']){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.04;layers.push(...printedArtwork(host,{target:host.catmAssembly.labels[face],url:sources[face],size:v.size,position,face,depth:.1,name:'CatM exact own '+face+' source artwork raster',artworkKind:'source-vector-raster'})??[]);}return layers;}
